LOW, HIGH = 10, 99


def is_answer(product):
    # Replace with the problem's test.
    # (This example: every digit of the product is even.)
    return all(int(d) % 2 == 0 for d in str(product))


def solve():
    best = 0
    for a in range(HIGH, LOW - 1, -1):
        if a * HIGH <= best:           # nothing in this row or below can win
            break
        for b in range(HIGH, a - 1, -1):
            product = a * b
            if product <= best:        # the rest of this row is smaller still
                break
            if is_answer(product):
                best = product
    return best


